function render(){
  const pages={dashboard:dashboardPage,executive:dashboardPage,orders:ordersPage,warehouse:warehousePage,stock:stockPage,counts:countsPage,transfers:transfersPage,delivery:deliveryPage,profit:profitPage,customer360:customer360Page,stockhealth:stockHealthPage,deliveryperformance:deliveryPerformancePage,costvariance:costVariancePage,reports:reportsPage,customers:customersPage,masters:mastersPage,users:usersPage,settings:settingsPage,audit:auditPage,commercial:commercialPage,inactive:inactivePage};
  $('#page').innerHTML=(pages[state.page]||dashboardPage)();wireSort();wirePage();
}
function wirePage(){
  $$('[data-action]').forEach(b=>b.onclick=()=>{const action=actions[b.dataset.action];if(!action)return toast(`ปุ่ม ${b.dataset.action} ยังไม่พร้อมใช้งาน`,true);action(b.dataset.id)});
  $$('[data-go]').forEach(b=>b.onclick=()=>go(b.dataset.go));
  $$('[data-profit-view]').forEach(b=>b.onclick=()=>{state.profitView=b.dataset.profitView;render()});
  const search=$('#pageSearch');if(search){search.value=state.search;search.oninput=()=>{state.search=search.value.toLowerCase();render()}}
  const year=$('#reportYear');if(year){year.value=state.reportYear;year.onchange=()=>{state.reportYear=year.value;render()}}
  const wh=$('#reportWarehouse');if(wh){wh.value=state.reportWarehouse;wh.onchange=()=>{state.reportWarehouse=wh.value;render()}}
  const customer=$('#reportCustomer');if(customer){customer.value=state.reportCustomer;customer.onchange=()=>{state.reportCustomer=customer.value;render()}}
  const movementWarehouse=$('#movementWarehouse');if(movementWarehouse){movementWarehouse.value=state.movementWarehouse;movementWarehouse.onchange=()=>{state.movementWarehouse=movementWarehouse.value;render()}}
  const movementProduct=$('#movementProduct');if(movementProduct){movementProduct.value=state.movementProduct;movementProduct.onchange=()=>{state.movementProduct=movementProduct.value;render()}}
  const movementType=$('#movementType');if(movementType){movementType.value=state.movementType;movementType.onchange=()=>{state.movementType=movementType.value;render()}}
  const movementFrom=$('#movementFrom');if(movementFrom){movementFrom.value=state.movementFrom;movementFrom.onchange=()=>{state.movementFrom=movementFrom.value;render()}}
  const movementTo=$('#movementTo');if(movementTo){movementTo.value=state.movementTo;movementTo.onchange=()=>{state.movementTo=movementTo.value;render()}}
}
const byId=(list,id)=>state.data[list]?.find(x=>x.id===id);
const customerName=id=>byId('customers',id)?.name||'-';const product=id=>byId('products',id)||{};const warehouse=id=>byId('warehouses',id)||{};
const orderLines=id=>state.data.orderLines.filter(x=>x.order_id===id);const tripLines=id=>state.data.tripLines.filter(x=>x.trip_id===id);const transferLine=id=>state.data.transferLines.find(x=>x.transfer_id===id);
const stockAvailable=(pid,wid)=>{const b=state.data.balances.find(x=>x.product_id===pid&&x.warehouse_id===wid);return Number(b?.on_hand||0)-Number(b?.allocated||0)};

const invoiceGross=i=>Number(i.revenue||0)-Number(i.product_cost||0);
const invoiceContribution=i=>invoiceGross(i)-Number(i.freight_cost||0)-Number(i.other_cost||0);
const invoiceGp=invoiceContribution;
const compactMoney=n=>{const v=Number(n||0);return Math.abs(v)>=1000000?`฿${(v/1000000).toFixed(2)}m`:Math.abs(v)>=1000?`฿${(v/1000).toFixed(1)}k`:money(v)};
const invoiceOrderId=id=>state.data.invoiceOrders?.find(x=>x.invoice_id===id)?.order_id;
function analyticsYears(){const years=new Set([String(new Date().getFullYear()),...(state.data.invoices||[]).map(x=>String(new Date(x.invoice_date).getFullYear())).filter(x=>x!=='NaN')]);return [...years].sort((a,b)=>b-a)}
function analyticsInvoices(){return (state.data.invoices||[]).filter(i=>{const y=String(new Date(i.invoice_date).getFullYear());if(y!==state.reportYear)return false;if(state.reportCustomer!=='ALL'&&i.customer_id!==state.reportCustomer)return false;if(state.reportWarehouse==='ALL')return true;const oid=invoiceOrderId(i.id);return oid&&orderLines(oid).some(l=>l.warehouse_id===state.reportWarehouse)})}
function analyticsTrips(){return (state.data.trips||[]).filter(t=>{if(String(new Date(t.planned_start).getFullYear())!==state.reportYear)return false;if(state.reportWarehouse==='ALL')return true;return orderLines(t.order_id).some(l=>l.warehouse_id===state.reportWarehouse)})}
function analyticsBalances(){return (state.data.balances||[]).filter(b=>state.reportWarehouse==='ALL'||b.warehouse_id===state.reportWarehouse)}
function analyticsFilters({year=true,warehouse=true,customer=false}={}){return `${year?`<select id="reportYear" aria-label="ปี">${analyticsYears().map(y=>`<option value="${y}">ปี ${y}</option>`).join('')}</select>`:''}${warehouse?`<select id="reportWarehouse" aria-label="คลัง"><option value="ALL">ทุกคลัง</option>${state.data.warehouses.map(w=>`<option value="${w.id}">${esc(w.code)} • ${esc(w.name)}</option>`).join('')}</select>`:''}${customer?`<select id="reportCustomer" aria-label="ลูกค้า"><option value="ALL">ลูกค้าทั้งหมด</option>${state.data.customers.filter(x=>x.active!==false).map(x=>`<option value="${x.id}">${esc(x.code)} • ${esc(x.name)}</option>`).join('')}</select>`:''}`}
function monthlySeries(invoices=analyticsInvoices()){const months=Array.from({length:12},(_,i)=>({label:new Intl.DateTimeFormat('th-TH',{month:'short'}).format(new Date(2026,i,1)),sales:0,gp:0,count:0}));invoices.forEach(x=>{const m=new Date(x.invoice_date).getMonth();if(months[m]){months[m].sales+=Number(x.revenue||0);months[m].gp+=invoiceGp(x);months[m].count++}});return months}
function ownerChart(invoices=analyticsInvoices()){const series=monthlySeries(invoices),max=Math.max(1,...series.map(x=>x.sales));return `<div class="panel"><div class="section-title"><div><h3>ยอดขาย & Contribution รายเดือน</h3><span class="muted">ข้อมูล Invoice จริง • ${esc(state.reportYear)}</span></div></div><div class="chart-legend"><b>ยอดขาย</b><span>● Contribution Profit</span></div><div class="chart">${series.map(x=>{const bar=Math.max(2,Math.round(x.sales/max*175)),gp=x.sales?Math.max(0,Math.min(100,Math.round(x.gp/x.sales*100))):0;return `<div class="chart-col" title="${esc(x.label)} • Sales ${money(x.sales)} • Contribution ${money(x.gp)}"><div class="chart-value">${x.sales?compactMoney(x.sales).replace('฿',''):''}</div><div class="chart-bar" style="--bar:${bar}px"><div class="chart-gp" style="--gp:${gp}%"></div></div><div class="chart-label">${esc(x.label)}</div></div>`}).join('')}</div><p class="muted">แท่งเต็ม = Sales • แท่งเข้ม = Contribution Profit</p></div>`}
function customerProfitRows(invoices=analyticsInvoices()){const map=new Map();invoices.forEach(i=>{const k=i.customer_id,r=map.get(k)||{sales:0,gp:0,count:0};r.sales+=Number(i.revenue||0);r.gp+=invoiceGp(i);r.count++;map.set(k,r)});return [...map].map(([id,v])=>({id,name:customerName(id),...v,pct:v.sales?v.gp/v.sales*100:0})).sort((a,b)=>b.gp-a.gp)}
function productSalesRows(invoices=analyticsInvoices()){const allowed=new Set(invoices.map(i=>invoiceOrderId(i.id)).filter(Boolean)),map=new Map();state.data.orderLines.filter(l=>allowed.has(l.order_id)).forEach(l=>{const p=product(l.product_id),group=byId('productGroups',p.group_id),key=group?.name||String(p.code||'อื่น').slice(0,3)||'อื่น',v=map.get(key)||0;map.set(key,v+Number(l.qty||0)*Number(l.unit_price||0))});return [...map].map(([name,sales])=>({name,sales})).sort((a,b)=>b.sales-a.sales)}
function metricBars(rows,valueKey,labelKey){const max=Math.max(1,...rows.map(x=>Math.abs(x[valueKey])));return `<div class="metric-list">${rows.slice(0,5).map(x=>`<div class="metric-line"><span>${esc(x[labelKey])}</span><b>${compactMoney(x[valueKey])}</b><div class="progress"><span style="width:${Math.max(3,Math.round(Math.abs(x[valueKey])/max*100))}%"></span></div></div>`).join('')||empty()}</div>`}

function dashboardPage(){
  const revenue=state.data.invoices.reduce((s,x)=>s+Number(x.revenue||0),0),gp=state.data.invoices.reduce((s,x)=>s+Number(x.revenue||0)-Number(x.product_cost||0)-Number(x.freight_cost||0)-Number(x.other_cost||0),0),open=state.data.orders.filter(x=>!['DELIVERED','CANCELLED'].includes(x.status)).length,stock=state.data.balances.reduce((s,x)=>s+Number(x.on_hand||0),0);
  const recent=state.data.orders.slice(0,8).map(o=>`<tr><td><b>${esc(o.order_no)}</b></td><td>${esc(customerName(o.customer_id))}</td><td>${dmy(o.order_date)}</td><td>${badge(o.status)}</td><td class="num" data-sort="${orderLines(o.id).reduce((s,l)=>s+Number(l.qty),0)}">${qty(orderLines(o.id).reduce((s,l)=>s+Number(l.qty),0))}</td></tr>`);
  if(can('ADMIN')&&state.page==='dashboard'){const pending=state.data.accessRequests.filter(x=>x.status==='PENDING').length,today=new Date().toISOString().slice(0,10),todayOrders=state.data.orders.filter(x=>String(x.order_date).slice(0,10)===today).length;return head('Admin Control Center','ควบคุมข้อมูล ผู้ใช้ และการตั้งค่าระบบ')+cards([['Orders วันนี้',nf.format(todayOrders),'รายการ'],['คลังสินค้า',nf.format(state.data.warehouses.length),'คลัง'],['Users',nf.format(state.data.users.length),'บัญชี'],['รออนุมัติ',nf.format(pending),'คำขอ']])+`<div class="split"><div class="panel"><h3>งานที่ต้องติดตาม</h3><div class="analytics-alert"><strong>${pending} ผู้ใช้รออนุมัติ</strong><button class="btn small-btn" data-go="users">เปิด</button></div><div class="analytics-alert"><strong>${open} Orders ยังไม่ปิด</strong><button class="btn small-btn" data-go="orders">เปิด</button></div><div class="analytics-alert"><strong>${state.data.trips.filter(x=>x.status!=='COMPLETED').length} เที่ยวส่งยังไม่เสร็จ</strong><button class="btn small-btn" data-go="delivery">เปิด</button></div></div><div class="panel"><h3>ทางลัด Admin</h3><div class="tabs"><button class="tab-pill" data-go="masters">Master Data</button><button class="tab-pill" data-go="settings">Business Rules</button><button class="tab-pill" data-go="reports">Reports</button><button class="tab-pill" data-go="executive">Executive Dashboard</button>${state.isPlatformAdmin?'<button class="tab-pill" data-go="commercial">Commercial Control</button>':''}</div></div></div><div class="panel"><h3>Orders ล่าสุด</h3>${table(['Order','ลูกค้า','วันที่','สถานะ','จำนวน'],recent)}</div>`}
  if(!can('OWNER')&&state.page!=='executive')return head('ภาพรวมวันนี้','ข้อมูลจริงจากฐานข้อมูล FlowStock')+cards([['Sales',money(revenue),'Invoice ทั้งหมด'],['Contribution Profit',money(gp),revenue?`Contribution ${(gp/revenue*100).toFixed(2)}%`:'' ],['Open Orders',nf.format(open),'รายการที่ยังไม่ปิด'],['Stock On Hand',qty(stock),'ทุกคลัง']])+`<div class="panel"><h3>Orders ล่าสุด</h3>${table(['Order','ลูกค้า','วันที่','สถานะ','จำนวน'],recent)}</div>`;
  const inv=analyticsInvoices(),filteredBalances=analyticsBalances(),filteredTrips=analyticsTrips(),sales=inv.reduce((s,x)=>s+Number(x.revenue||0),0),profit=inv.reduce((s,x)=>s+invoiceGp(x),0),stockValue=filteredBalances.reduce((s,b)=>{const costs=state.data.costs.filter(c=>c.product_id===b.product_id).sort((a,z)=>String(z.cost_month).localeCompare(String(a.cost_month)));return s+Number(b.on_hand||0)*Number(costs[0]?.unit_cost||0)},0),waiting=state.data.orders.filter(x=>x.status==='WAITING_LOGISTICS'&&(state.reportWarehouse==='ALL'||orderLines(x.id).some(l=>l.warehouse_id===state.reportWarehouse))).length,late=filteredTrips.filter(x=>x.status!=='COMPLETED'&&x.planned_end&&new Date(x.planned_end)<new Date()).length,low=filteredBalances.filter(x=>Number(x.on_hand||0)<=0).length,lowGp=inv.filter(x=>Number(x.revenue)>0&&invoiceGp(x)/Number(x.revenue)*100<12).length,freightVariance=inv.reduce((s,x)=>s+Number(x.freight_cost||0),0)-filteredTrips.reduce((s,t)=>s+Number(t.standard_freight||0),0);
  const alerts=[[`🚚 ${waiting} Orders ยังไม่มีรถ`,'deliveryperformance'],[`⏱ ${late} เที่ยวส่งล่าช้า`,'deliveryperformance'],[`📦 ${low} รายการ Stock หมด/ติดศูนย์`,'stockhealth'],[`💸 Freight Actual ต่างจาก Standard ${compactMoney(freightVariance)}`,'costvariance'],[`📉 ${lowGp} Invoice มี Contribution ต่ำกว่า 12%`,'profit']];
  const gross=inv.reduce((s,x)=>s+invoiceGross(x),0);return head('ภาพรวมธุรกิจ','Owner Dashboard • วันนี้ต้องรู้อะไร',analyticsFilters())+cards([['ยอดขาย',compactMoney(sales),`ปี ${state.reportYear}`],['Gross Profit',compactMoney(gross),'Sales − Product Cost'],['Contribution Profit',compactMoney(profit),inv.some(x=>x.gp_status==='ESTIMATED')?'Estimated/Final แยกชัดเจน':'Final'],['Contribution %',sales?(profit/sales*100).toFixed(2)+'%':'0.00%','จาก Invoice'],['Stock Value',compactMoney(stockValue),state.reportWarehouse==='ALL'?`${state.data.warehouses.length} คลัง`:'คลังที่เลือก']])+`<div class="panel"><h3>สิ่งที่ต้องรู้วันนี้</h3>${alerts.map(a=>`<div class="analytics-alert"><strong>${esc(a[0])}</strong><button class="btn small-btn" data-go="${a[1]}">ดู</button></div>`).join('')}</div>${ownerChart(inv)}<div class="split"><div class="panel"><h3>ยอดขายตามกลุ่มสินค้า</h3>${metricBars(productSalesRows(inv),'sales','name')}</div><div class="panel"><h3>Top Customer Contribution</h3>${metricBars(customerProfitRows(inv),'gp','name')}</div></div>`;
}
function ordersPage(){
  const q=state.search,rows=state.data.orders.filter(o=>`${o.order_no} ${customerName(o.customer_id)} ${o.status}`.toLowerCase().includes(q)).map(o=>{const ls=orderLines(o.id),amount=ls.reduce((s,l)=>s+Number(l.qty)*Number(l.unit_price),0);return `<tr><td><b>${esc(o.order_no)}</b></td><td>${esc(customerName(o.customer_id))}</td><td>${dmy(o.order_date)}</td><td>${badge(o.status)}</td><td class="num" data-sort="${amount}">${money(amount)}</td><td><button class="btn small-btn" data-action="viewOrder" data-id="${o.id}">เปิด</button></td></tr>`});
  return head('Orders','สร้างและติดตามคำสั่งขาย',`${can('SALES','ADMIN')?'<button class="btn primary" data-action="newOrder">+ สร้าง Order</button>':''}<button class="btn" data-action="exportOrders">ดาวน์โหลด CSV</button>`)+`<div class="toolbar"><input id="pageSearch" placeholder="ค้นหา Order / ลูกค้า / สถานะ"></div><div class="panel">${table(['Order','ลูกค้า','วันที่','สถานะ','มูลค่า',''],rows)}</div>`;
}
function customersPage(){const rows=state.data.customers.filter(x=>`${x.code} ${x.name} ${x.region}`.toLowerCase().includes(state.search)).map(x=>`<tr><td><b>${esc(x.code)}</b></td><td>${esc(x.name)}</td><td>${esc(x.region||'-')}</td><td>${x.active?badge('ACTIVE'):badge('INACTIVE')}</td></tr>`);return head('ลูกค้า','ข้อมูลลูกค้าในบริษัท')+`<div class="toolbar"><input id="pageSearch" placeholder="ค้นหาลูกค้า"></div><div class="panel">${table(['รหัส','ชื่อลูกค้า','ภูมิภาค','สถานะ'],rows)}</div>`}
function warehousePage(){
  const jobs=state.data.orders.filter(o=>['CONFIRMED','PARTIAL_ISSUE'].includes(o.status)).map(o=>{const ls=orderLines(o.id),rem=ls.reduce((s,l)=>s+Number(l.qty)-Number(l.issued_qty||0),0);return `<tr><td><b>${esc(o.order_no)}</b></td><td>${esc(customerName(o.customer_id))}</td><td class="num">${qty(rem)}</td><td>${badge(o.status)}</td><td><button class="btn primary small-btn" data-action="issueOrder" data-id="${o.id}">จ่ายสินค้า</button></td></tr>`});
  const rec=state.data.receipts.slice(0,8).map(r=>`<tr><td><b>${esc(r.gr_no)}</b></td><td>${esc(warehouse(r.warehouse_id).code)}</td><td>${esc(r.source_doc_no||'-')}</td><td>${dmy(r.receipt_date)}</td><td>${badge(r.status)}</td></tr>`);
  return head('งานคลัง','รับเข้า จ่ายออก และตรวจสอบงานค้าง','<button class="btn primary" data-action="newReceipt">+ รับสินค้า</button>')+cards([['รอจ่าย',nf.format(jobs.length),'Orders'],['รับเข้าวันนี้',nf.format(state.data.receipts.filter(x=>x.receipt_date===new Date().toISOString().slice(0,10)).length),'เอกสาร'],['Stock รวม',qty(state.data.balances.reduce((s,x)=>s+Number(x.on_hand),0)),'ทุกคลัง'],['โอนค้างรับ',nf.format(state.data.transfers.filter(x=>x.status==='IN_TRANSIT').length),'Transfers']])+`<div class="split"><div class="panel"><h3>งานรอจ่าย</h3>${table(['Order','ลูกค้า','คงเหลือต้องจ่าย','สถานะ',''],jobs)}</div><div class="panel"><h3>รับสินค้าล่าสุด</h3>${table(['GR','คลัง','เอกสารอ้างอิง','วันที่','สถานะ'],rec)}</div></div>`;
}
const movementTypeThai={RECEIPT:'รับเข้า',OPENING_BALANCE:'ยอดยกมา',TRANSFER_OUT:'โอนออก',TRANSFER_IN:'โอนเข้า',ORDER_ISSUE:'จ่ายตาม Order',COUNT_ADJUSTMENT:'ปรับจากตรวจนับ'};
const movementDirection=m=>Number(m.qty)>=0?'IN':'OUT';
function movementRows(){
  const all=[...(state.data.movements||[])].sort((a,b)=>{const x=String(a.created_at).localeCompare(String(b.created_at));return x||String(a.id).localeCompare(String(b.id))});
  const balances=new Map(),withBalance=all.map(m=>{const key=`${m.warehouse_id}|${m.product_id}`,next=(balances.get(key)||0)+Number(m.qty||0);balances.set(key,next);return {...m,balanceAfter:next}});
  return withBalance.filter(m=>{
    const p=product(m.product_id),w=warehouse(m.warehouse_id),q=`${p.code||''} ${p.name||''} ${w.code||''} ${w.name||''} ${m.reference_no||''} ${movementTypeThai[m.movement_type]||m.movement_type}`.toLowerCase();
    const day=String(m.created_at||'').slice(0,10),dir=movementDirection(m);
    return (!state.search||q.includes(state.search))&&(state.movementWarehouse==='ALL'||m.warehouse_id===state.movementWarehouse)&&(state.movementProduct==='ALL'||m.product_id===state.movementProduct)&&(state.movementType==='ALL'||(state.movementType==='IN'?dir==='IN':state.movementType==='OUT'?dir==='OUT':m.movement_type===state.movementType))&&(!state.movementFrom||day>=state.movementFrom)&&(!state.movementTo||day<=state.movementTo);
  }).sort((a,b)=>String(b.created_at).localeCompare(String(a.created_at)));
}
function stockPage(){
  const rows=state.data.balances.filter(b=>`${product(b.product_id).code} ${product(b.product_id).name} ${warehouse(b.warehouse_id).code} ${warehouse(b.warehouse_id).name}`.toLowerCase().includes(state.search)).map(b=>{const p=product(b.product_id),w=warehouse(b.warehouse_id),avail=Number(b.on_hand)-Number(b.allocated);return `<tr><td><b>${esc(p.code)}</b> ${esc(p.name)}</td><td>${esc(w.code)} ${esc(w.name)}</td><td class="num" data-sort="${b.on_hand}">${qty(b.on_hand)}</td><td class="num">${qty(b.allocated)}</td><td class="num"><b>${qty(avail)}</b></td><td>${esc(p.base_uom||'')}</td></tr>`});
  const moves=movementRows().slice(0,500).map(m=>{const p=product(m.product_id),w=warehouse(m.warehouse_id),inQty=Number(m.qty)>0?Number(m.qty):0,outQty=Number(m.qty)<0?Math.abs(Number(m.qty)):0;return `<tr><td>${dmy(m.created_at)}</td><td><b>${esc(p.code)}</b> ${esc(p.name||'')}</td><td>${esc(w.code)}</td><td>${esc(movementTypeThai[m.movement_type]||m.movement_type)}</td><td>${esc(m.reference_no||'-')}</td><td class="num positive" data-sort="${inQty}">${inQty?qty(inQty):'-'}</td><td class="num negative" data-sort="${outQty}">${outQty?qty(outQty):'-'}</td><td class="num" data-sort="${m.balanceAfter}"><b>${qty(m.balanceAfter)}</b></td></tr>`});
  const typeOpts=['ALL','IN','OUT',...Object.keys(movementTypeThai)].map(x=>`<option value="${x}">${x==='ALL'?'ทุกประเภท':x==='IN'?'เข้า':x==='OUT'?'ออก':movementTypeThai[x]}</option>`).join('');
  return head('Stock','ยอดคงเหลือและ Stock Movement ตาม mockup',`<button class="btn" data-action="exportStock">ดาวน์โหลด Stock</button><button class="btn" data-action="exportMovements">Export Movement</button><button class="btn" data-action="emailStockReport">ส่งรายงาน</button>`)+`<div class="panel"><h3>ยอดคงเหลือ</h3>${table(['สินค้า','คลัง','On Hand','Allocated','Available','UoM'],rows)}</div><div class="panel"><div class="page-head"><div><h3>Stock Movement</h3><p>ยอดเข้า / ออก / คงเหลือหลังรายการ</p></div></div><div class="toolbar"><input id="pageSearch" placeholder="ค้นหาสินค้า / คลัง / เอกสาร"><select id="movementWarehouse"><option value="ALL">ทุกคลัง</option>${option('warehouses',x=>`${x.code} • ${x.name}`)}</select><select id="movementProduct"><option value="ALL">ทุกสินค้า</option>${option('products',x=>`${x.code} • ${x.name}`)}</select><select id="movementType">${typeOpts}</select><label class="date-filter">ตั้งแต่ <input id="movementFrom" type="date"></label><label class="date-filter">ถึง <input id="movementTo" type="date"></label></div>${table(['วันที่','สินค้า','คลัง','ประเภท','อ้างอิง','In','Out','Balance'],moves)}</div>`;
}
function countVariance(c){return state.data.countLines.filter(x=>x.count_id===c.id).reduce((s,x)=>s+(x.count_qty==null?0:Number(x.count_qty)-Number(x.book_qty||0)),0)}
function countsPage(){const rows=state.data.counts.map(c=>{const ls=state.data.countLines.filter(x=>x.count_id===c.id),variance=countVariance(c),action=c.status==='DRAFT'?`<button class="btn small-btn" data-action="openCount" data-id="${c.id}">ทำต่อ</button>`:c.status==='SUBMITTED'&&can('ADMIN')?`<button class="btn primary small-btn" data-action="finalizeCount" data-id="${c.id}">Admin Final</button> <button class="btn small-btn" data-action="openCount" data-id="${c.id}">ดูผล</button>`:`<button class="btn small-btn" data-action="openCount" data-id="${c.id}">ดูผล</button>`;return `<tr><td><b>${esc(c.count_no)}</b></td><td>${esc(warehouse(c.warehouse_id).code)}</td><td>${dmy(c.snapshot_at)}</td><td class="num">${nf.format(ls.length)}</td><td class="num ${variance?'negative':''}">${qty(variance)}</td><td>${badge(c.status)}</td><td>${action}</td></tr>`});return head('ตรวจนับ Stock','Snapshot → นับหลายกอง → Submit → Admin Final Adjustment','<button class="btn primary" data-action="newCount">+ เริ่มรอบตรวจนับ</button>')+`<div class="alert warn">การบันทึกยอดตรวจยังไม่เปลี่ยน Stock ทันที ยอดจะเปลี่ยนเมื่อ Admin กด Final Adjustment เท่านั้น</div><div class="panel">${table(['Count No.','คลัง','Snapshot','สินค้า','ส่วนต่างสุทธิ','สถานะ',''],rows)}</div>`}
function transfersPage(){const rows=state.data.transfers.map(t=>{const l=transferLine(t.id)||{};return `<tr><td><b>${esc(t.transfer_no)}</b></td><td>${esc(warehouse(t.from_warehouse_id).code)}</td><td>${esc(warehouse(t.to_warehouse_id).code)}</td><td>${esc(product(l.product_id).code||'-')}</td><td class="num">${qty(l.sent_qty)}</td><td class="num">${l.received_qty==null?'-':qty(l.received_qty)}</td><td>${badge(t.status)}</td><td>${t.status==='IN_TRANSIT'?`<button class="btn primary small-btn" data-action="receiveTransfer" data-id="${t.id}">รับปลายทาง</button>`:''}</td></tr>`});return head('โอนระหว่างคลัง','ตัดต้นทางเมื่อส่ง และเพิ่มปลายทางเมื่อรับจริง','<button class="btn primary" data-action="newTransfer">+ สร้างใบโอน</button>')+`<div class="panel">${table(['Transfer','จาก','ไป','สินค้า','ส่ง','รับจริง','สถานะ',''],rows)}</div>`}
function deliveryPage(){
  const ready=state.data.orders.filter(o=>o.status==='WAITING_LOGISTICS').map(o=>`<tr><td><b>${esc(o.order_no)}</b></td><td>${esc(customerName(o.customer_id))}</td><td>${dmy(o.requested_delivery_at)}</td><td class="num">${qty(orderLines(o.id).reduce((s,l)=>s+Number(l.issued_qty||0),0))}</td><td>${can('LOGISTICS','ADMIN')?`<button class="btn primary small-btn" data-action="newTrip" data-id="${o.id}">จัดรถ</button>`:''}</td></tr>`);
  const trips=state.data.trips.map(t=>{const o=byId('orders',t.order_id),doc=state.data.deliveryDocs?.find(d=>d.trip_id===t.id);return `<tr><td><b>${esc(t.trip_no)}</b></td><td>${esc(o?.order_no||'-')}</td><td>${esc(customerName(o?.customer_id))}</td><td>${dmy(t.planned_start)}</td><td>${esc(byId('vehicles',t.vehicle_id)?.plate_no||'-')}</td><td>${badge(t.status)}</td><td>${t.status!=='COMPLETED'&&can('LOGISTICS','ADMIN')?`<button class="btn primary small-btn" data-action="completeTrip" data-id="${t.id}">POD / ปิดงาน</button>`:doc?`<button class="btn small-btn" data-action="openPod" data-id="${doc.id}">เปิด POD</button>`:esc(t.pod_reference||'-')}</td></tr>`});
  return head('ขนส่ง / POD','จัดรถ ตรวจเวลาซ้อน และบันทึกลูกค้ารับจริง')+`<div class="split"><div class="panel"><h3>รอจัดรถ</h3>${table(['Order','ลูกค้า','กำหนดส่ง','จำนวน',''],ready)}</div><div class="panel"><h3>เที่ยวส่ง</h3>${table(['Trip','Order','ลูกค้า','เวลา','รถ','สถานะ',''],trips)}</div></div>`;
}
function profitBreakdown(dimension,invoices){
  const map=new Map(),add=(key,label,i,share=1)=>{const row=map.get(key)||{label,sales:0,productCost:0,freight:0,other:0,invoices:new Set()};row.sales+=Number(i.revenue||0)*share;row.productCost+=Number(i.product_cost||0)*share;row.freight+=Number(i.freight_cost||0)*share;row.other+=Number(i.other_cost||0)*share;row.invoices.add(i.id);map.set(key,row)};
  invoices.forEach(i=>{
    if(dimension==='customer')return add(i.customer_id,customerName(i.customer_id),i);
    const oid=invoiceOrderId(i.id),all=oid?orderLines(oid):[],total=all.reduce((s,l)=>s+Number(l.qty||0)*Number(l.unit_price||0),0),selected=all.filter(l=>state.reportWarehouse==='ALL'||l.warehouse_id===state.reportWarehouse);
    if(!selected.length)return add('unassigned','ไม่ระบุ',i);
    selected.forEach(l=>{const p=product(l.product_id),lineValue=Number(l.qty||0)*Number(l.unit_price||0),share=total?lineValue/total:1/selected.length;if(dimension==='product')add(l.product_id,`${p.code||'-'} • ${p.name||'-'}`,i,share);if(dimension==='group'){const pg=byId('productGroups',p.group_id),group=pg?.name||String(p.code||'อื่น').slice(0,3)||'อื่น';add(pg?.id||group,group,i,share)}if(dimension==='warehouse'){const w=warehouse(l.warehouse_id);add(l.warehouse_id,`${w.code||'-'} • ${w.name||'-'}`,i,share)}});
  });
  return [...map.values()].map(r=>({...r,gross:r.sales-r.productCost,contribution:r.sales-r.productCost-r.freight-r.other,pct:r.sales?(r.sales-r.productCost-r.freight-r.other)/r.sales*100:0})).sort((a,b)=>b.sales-a.sales)
}
function profitTable(view,invoices){
  if(view==='invoice'){const rows=invoices.map(i=>{const gross=invoiceGross(i),contribution=invoiceContribution(i),pct=Number(i.revenue)?contribution/Number(i.revenue)*100:0;return `<tr><td><b>${esc(i.invoice_no)}</b></td><td>${dmy(i.invoice_date)}</td><td>${esc(customerName(i.customer_id))}</td><td class="num">${money(i.revenue)}</td><td class="num">${money(i.product_cost)}</td><td class="num"><b>${money(gross)}</b></td><td class="num">${money(i.freight_cost)}</td><td class="num">${money(i.other_cost)}</td><td class="num"><b>${money(contribution)}</b></td><td class="num ${pct<12?'negative':''}">${pct.toFixed(2)}%</td><td>${badge(i.gp_status)}</td></tr>`});return table(['Invoice','วันที่','ลูกค้า','Revenue','Product Cost','Gross Profit','Freight','Direct Expense','Contribution','Contribution %','สถานะ'],rows)}
  const labels={product:'สินค้า',group:'กลุ่มสินค้า',customer:'ลูกค้า',warehouse:'คลัง'},rows=profitBreakdown(view,invoices).map(r=>`<tr><td><b>${esc(r.label)}</b></td><td class="num">${money(r.sales)}</td><td class="num">${money(r.productCost)}</td><td class="num"><b>${money(r.gross)}</b></td><td class="num">${money(r.freight)}</td><td class="num">${money(r.other)}</td><td class="num"><b>${money(r.contribution)}</b></td><td class="num ${r.pct<12?'negative':''}">${r.pct.toFixed(2)}%</td><td class="num">${nf.format(r.invoices.size)}</td></tr>`);return table([labels[view],'Revenue','Product Cost','Gross Profit','Freight','Direct Expense','Contribution','Contribution %','Invoice'],rows)
}
function profitPage(){const inv=analyticsInvoices(),rev=inv.reduce((s,x)=>s+Number(x.revenue),0),gross=inv.reduce((s,x)=>s+invoiceGross(x),0),contribution=inv.reduce((s,x)=>s+invoiceContribution(x),0),tabs=[['product','By Product'],['group','By Product Group'],['customer','By Customer'],['invoice','By Invoice'],['warehouse','By Warehouse']];return head('Sales & Profit 360°','Gross Profit ทางบัญชี และ Contribution Profit หลังค่าขนส่ง/ค่าใช้จ่ายตรง',analyticsFilters({customer:true}))+cards([['Sales',compactMoney(rev),`ปี ${state.reportYear}`],['Gross Profit',compactMoney(gross),'Sales − Product Cost'],['Contribution Profit',compactMoney(contribution),'Gross − Freight − Direct Expense'],['Contribution %',rev?(contribution/rev*100).toFixed(2)+'%':'0.00%',''],['Invoices',nf.format(inv.length),'รายการ']])+ownerChart(inv)+`<div class="panel"><div class="tabs">${tabs.map(([key,label])=>`<button type="button" class="tab-pill ${state.profitView===key?'active':''}" data-profit-view="${key}">${label}</button>`).join('')}</div>${profitTable(state.profitView,inv)}</div>`}

function customer360Page(){const rows=customerProfitRows().filter(x=>`${x.name}`.toLowerCase().includes(state.search)).map(x=>`<tr><td><b>${esc(x.name)}</b></td><td class="num">${money(x.sales)}</td><td class="num">${money(x.gp)}</td><td class="num ${x.pct<12?'negative':''}">${x.pct.toFixed(2)}%</td><td class="num">${nf.format(x.count)}</td><td><button class="btn small-btn" data-action="openCustomerProfit" data-id="${x.id}">ดู Invoice</button></td></tr>`);return head('Customer 360°','ยอดขาย • Gross Profit • Contribution Profit',analyticsFilters())+`<div class="toolbar"><input id="pageSearch" placeholder="ค้นหาลูกค้า"></div>`+cards([['ลูกค้าที่ซื้อ',nf.format(customerProfitRows().length),'ราย'],['ยอดขาย',compactMoney(analyticsInvoices().reduce((s,x)=>s+Number(x.revenue||0),0)),''],['Gross Profit',compactMoney(analyticsInvoices().reduce((s,x)=>s+invoiceGross(x),0)),'Sales − Product Cost'],['Contribution Profit',compactMoney(analyticsInvoices().reduce((s,x)=>s+invoiceContribution(x),0)),'หลัง Freight/Direct Expense'],['Invoice',nf.format(analyticsInvoices().length),'รายการ']])+`<div class="panel">${table(['ลูกค้า','ยอดขาย','Contribution','Contribution %','Invoice',''],rows)}</div>`}

function stockHealthPage(){const balances=analyticsBalances(),totalQty=balances.reduce((s,x)=>s+Number(x.on_hand||0),0),zero=balances.filter(x=>Number(x.on_hand||0)<=0),allowedWarehouses=state.reportWarehouse==='ALL'?state.data.warehouses:state.data.warehouses.filter(w=>w.id===state.reportWarehouse),allowedCounts=new Set(state.data.counts.filter(c=>state.reportWarehouse==='ALL'||c.warehouse_id===state.reportWarehouse).map(c=>c.id)),variance=state.data.countLines.filter(x=>allowedCounts.has(x.count_id)).reduce((s,x)=>s+Number(x.count_qty||0)-Number(x.book_qty||0),0),whRows=allowedWarehouses.map(w=>({name:`${w.code} • ${w.name}`,qty:balances.filter(b=>b.warehouse_id===w.id).reduce((s,b)=>s+Number(b.on_hand||0),0)})).sort((a,b)=>b.qty-a.qty),alertRows=zero.map(b=>`<tr><td><b>${esc(product(b.product_id).code||'-')}</b> ${esc(product(b.product_id).name||'')}</td><td>${esc(warehouse(b.warehouse_id).code||'-')}</td><td class="num negative">${qty(b.on_hand)}</td><td>${badge('INACTIVE')}</td></tr>`);return head('Stock Health','มูลค่า • Stock ต่ำ • Slow Moving • No Movement • ตรวจนับ',analyticsFilters({year:false}))+cards([['Stock On Hand',qty(totalQty),state.reportWarehouse==='ALL'?'ทุกคลัง':'คลังที่เลือก'],['Stock หมด/ติดศูนย์',nf.format(zero.length),'รายการ'],['คลังสินค้า',nf.format(allowedWarehouses.length),'คลัง'],['Count Variance',qty(variance),'จำนวนสุทธิ']])+`<div class="split"><div class="panel"><h3>Stock Alert</h3>${table(['สินค้า','คลัง','คงเหลือ','สถานะ'],alertRows)}</div><div class="panel"><h3>Stock ตามคลัง</h3>${metricBars(whRows,'qty','name')}</div></div><div class="panel"><button class="btn" data-go="stock">เปิด Stock Movement</button> <button class="btn" data-go="counts">เปิดรอบตรวจนับ Stock</button></div>`}

function deliveryPerformancePage(){const trips=analyticsTrips(),tripIds=new Set(trips.map(x=>x.id)),completed=trips.filter(x=>x.status==='COMPLETED'),late=trips.filter(x=>x.status!=='COMPLETED'&&x.planned_end&&new Date(x.planned_end)<new Date()),issued=state.data.tripLines.filter(x=>tripIds.has(x.trip_id)).reduce((s,x)=>s+Number(x.issued_qty||0),0),freight=analyticsInvoices().reduce((s,x)=>s+Number(x.freight_cost||0),0),vendorMap=new Map();trips.forEach(t=>{const name=t.transport_supplier_id?(byId('suppliers',t.transport_supplier_id)?.name||'Vendor'):'รถบริษัท',v=vendorMap.get(name)||{name,trips:0,freight:0};v.trips++;v.freight+=Number(t.actual_freight??t.standard_freight??0);vendorMap.set(name,v)});const waiting=state.data.orders.filter(x=>x.status==='WAITING_LOGISTICS'&&(state.reportWarehouse==='ALL'||orderLines(x.id).some(l=>l.warehouse_id===state.reportWarehouse))).length,vendorRows=[...vendorMap.values()].map(x=>`<tr><td><b>${esc(x.name)}</b></td><td class="num">${nf.format(x.trips)}</td><td class="num">${money(x.freight)}</td></tr>`);return head('Delivery Performance','รถบริษัท + รถจ้าง • ต้นทุน • On-time • Loss',analyticsFilters())+cards([['Completed',nf.format(completed.length),'Trips'],['Trips ทั้งหมด',nf.format(trips.length),'รายการ'],['Freight / Unit',issued?money(freight/issued):money(0),'ตามจำนวนส่ง'],['ส่งล่าช้า',nf.format(late.length),'ต้องติดตาม']])+`<div class="split"><div class="panel"><h3>Transport Vendor</h3>${table(['Vendor','Trips','Freight'],vendorRows)}</div><div class="panel"><h3>รายการต้องติดตาม</h3><div class="analytics-alert"><strong>${late.length} เที่ยวล่าช้า</strong><button class="btn small-btn" data-go="delivery">เปิดงาน</button></div><div class="analytics-alert"><strong>${waiting} Order ยังไม่มีรถ</strong><button class="btn small-btn" data-go="delivery">จัดรถ</button></div></div></div>`}

function costVariancePage(){const inv=analyticsInvoices(),productCost=inv.reduce((s,x)=>s+Number(x.product_cost||0),0),actualFreight=inv.reduce((s,x)=>s+Number(x.freight_cost||0),0),other=inv.reduce((s,x)=>s+Number(x.other_cost||0),0),standard=analyticsTrips().reduce((s,t)=>s+Number(t.standard_freight||0),0),variance=actualFreight-standard,rows=[['Freight',standard,actualFreight,variance],['Product Cost',productCost,productCost,0],['Other Cost',other,other,0]].map(x=>`<tr><td><b>${x[0]}</b></td><td class="num">${money(x[1])}</td><td class="num">${money(x[2])}</td><td class="num ${x[3]>0?'negative':x[3]<0?'positive':''}">${x[3]>0?'+':''}${money(x[3])}</td></tr>`);return head('Cost & Variance','หาสาเหตุที่ทำให้กำไรลด',analyticsFilters())+cards([['Product Cost',compactMoney(productCost),'Actual'],['Freight',compactMoney(actualFreight),`เทียบ Standard ${compactMoney(standard)}`],['Other Cost',compactMoney(other),'Actual'],['Freight Variance',compactMoney(variance),variance>0?'สูงกว่า Standard':'ไม่เกิน Standard']])+`<div class="panel"><h3>Variance ที่ควรรู้</h3>${table(['ประเภท','Standard','Actual','Variance'],rows)}</div>`}

